#!/usr/bin/env python3
"""hooks/dirty-tree-guard.py — detect uncommitted changes and unpushed commits at session end.

Fires on SubagentStop and Stop events. Checks the git repository whose
working directory is reachable from the hook event payload's 'cwd' field
(falling back to process cwd). Client-agnostic: works with Claude Code,
Codex, and Copilot. Emits GIT-HYGIENE-VIOLATION sentinel lines to stdout
and stderr — non-blocking.

Self-check:
  --self-check  exits 0 if git is reachable, 1 otherwise.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _lib  # noqa: E402


def _git_root(cwd: Path) -> Path | None:
    """Return the git root containing cwd, or None if not in a repo."""
    try:
        result = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            capture_output=True, text=True, check=False, cwd=str(cwd),
        )
        if result.returncode == 0:
            return Path(result.stdout.strip())
    except FileNotFoundError:
        pass
    return None


def _has_uncommitted(repo_root: Path) -> tuple[bool, str]:
    """Return (dirty, detail). detail is a short human-readable summary."""
    try:
        result = subprocess.run(
            ["git", "status", "--porcelain"],
            capture_output=True, text=True, check=False, cwd=str(repo_root),
        )
        if result.returncode != 0:
            return False, ""
        lines = [l for l in result.stdout.splitlines() if l.strip()]
        if lines:
            staged = [l for l in lines if l[0] != " " and l[0] != "?"]
            unstaged = [l for l in lines if l[1] != " " and l[0] == " "]
            untracked = [l for l in lines if l.startswith("??")]
            parts = []
            if staged:
                parts.append(f"{len(staged)} staged")
            if unstaged:
                parts.append(f"{len(unstaged)} unstaged")
            if untracked:
                parts.append(f"{len(untracked)} untracked")
            return True, ", ".join(parts) if parts else f"{len(lines)} changed"
        return False, ""
    except Exception:  # noqa: BLE001
        return False, ""


def _current_branch(repo_root: Path) -> str:
    try:
        result = subprocess.run(
            ["git", "branch", "--show-current"],
            capture_output=True, text=True, check=False, cwd=str(repo_root),
        )
        if result.returncode == 0:
            return result.stdout.strip()
    except FileNotFoundError:
        pass
    return "unknown"


def _unpushed_commits(repo_root: Path) -> int:
    """Return count of commits on HEAD not yet pushed to upstream."""
    try:
        result = subprocess.run(
            ["git", "rev-list", "--count", "@{u}..HEAD"],
            capture_output=True, text=True, check=False, cwd=str(repo_root),
        )
        if result.returncode == 0:
            return int(result.stdout.strip())
    except (FileNotFoundError, ValueError):
        pass
    return 0


def check_repo(cwd: Path) -> list[str]:
    """Return list of violation lines for the repo containing cwd."""
    repo = _git_root(cwd)
    if repo is None:
        return []

    violations = []
    dirty, detail = _has_uncommitted(repo)
    if dirty:
        branch = _current_branch(repo)
        violations.append(
            f"GIT-HYGIENE-VIOLATION: uncommitted changes in {repo} on branch '{branch}' ({detail})"
        )

    unpushed = _unpushed_commits(repo)
    if unpushed > 0:
        branch = _current_branch(repo)
        violations.append(
            f"GIT-HYGIENE-VIOLATION: {unpushed} unpushed commit(s) in {repo} on branch '{branch}'"
        )

    return violations


def main() -> None:
    if "--self-check" in sys.argv:
        try:
            subprocess.run(["git", "--version"], capture_output=True, check=True)
        except (FileNotFoundError, subprocess.CalledProcessError) as e:
            _lib.log("self-check FAIL: git not found:", e)
            sys.exit(1)
        _lib.log("self-check OK")
        sys.exit(0)

    try:
        event = json.load(sys.stdin)
    except (json.JSONDecodeError, EOFError):
        event = {}

    raw_cwd = (
        event.get("cwd")
        or event.get("workingDirectory")
        or os.getcwd()
    )
    cwd = Path(raw_cwd)

    violations = check_repo(cwd)

    if violations:
        for v in violations:
            _lib.log(v)
            print(v, flush=True)
    else:
        _lib.log("dirty-tree-guard: clean")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""hooks/no-verify-strip.py — wrapper preHook that strips --no-verify
from `git commit`. Per SPEC.md §10.3 + §10.5.2.

The git command line reaches this hook two ways: the command wrapper
sets WRAPPED_ARGV (the argv after `git`) and passes --mode=wrapper,
while the Claude PreToolUse path pipes the Bash command as JSON on
stdin. Either way the script detects whether the user requested a
bypass and, depending on settings.secret_scanning.allowNoVerifyBypass,
either strip silently, warn, or pass through.

Default (allowNoVerifyBypass=false): strip silently and log to the
audit pipeline.
Override (allowNoVerifyBypass=true):  the wrapper config simply
removes this hook from preHooks (and the one-month nag fires from
elsewhere).

Self-check:
  --self-check
"""
from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _lib  # noqa: E402


def git_argv_from_wrapper() -> list[str]:
    """The args after `git`, as JSON in WRAPPED_ARGV (command-wrapper path)."""
    try:
        return json.loads(os.environ.get("WRAPPED_ARGV", "[]"))
    except json.JSONDecodeError:
        return []


def git_argv_from_stdin() -> list[str]:
    """The args after `git`, parsed from a Claude PreToolUse JSON payload."""
    raw = sys.stdin.read()
    if not raw.strip():
        return []
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        return []
    cmd = (
        payload.get("command")
        or payload.get("tool_input", {}).get("command")
        or ""
    ) if isinstance(payload, dict) else ""
    parts = cmd.split()
    return parts[1:] if parts and parts[0] == "git" else []


def check_invocation(argv: list[str]) -> int:
    """argv is the args AFTER `git`. Returns 0 always (this is an
    advisory; the actual stripping happens in the wrapper)."""
    if not argv or argv[0] != "commit":
        return 0
    stripped = []
    bypass_seen = False
    for a in argv[1:]:
        if a in ("--no-verify", "-n"):
            bypass_seen = True
            continue
        stripped.append(a)
    if bypass_seen:
        _lib.log("`--no-verify` was present and is being stripped.")
        _lib.log("Per Common.md §3.6: the override format is non-negotiable; same principle here.")
        _lib.log("To allow bypass: set settings.secret_scanning.allowNoVerifyBypass=true (one-month nag fires).")
    return 0


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(add_help=True)
    parser.add_argument("--self-check", action="store_true")
    parser.add_argument("--mode", choices=["claude", "wrapper"], default=None,
                        help="invocation mode (set by the command wrapper)")
    parser.add_argument("rest", nargs=argparse.REMAINDER)
    args = parser.parse_args(argv)
    if args.self_check:
        return _lib.self_check_ok()
    if args.mode == "wrapper":
        return check_invocation(git_argv_from_wrapper())
    if args.mode == "claude" or not sys.stdin.isatty():
        return check_invocation(git_argv_from_stdin())
    return check_invocation(args.rest)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
"""hooks/secret-block.py — PreToolUse hook that denies Bash commands
containing secret-shaped strings before they execute.

Reads the canonical pattern set from hooks/patterns.json
(+ patterns.local.json if present). Belt-and-suspenders alongside the
secret-handling rules in Common.md §4. Per SPEC.md §10.1.

Input contract (Claude Code PreToolUse):
  - The full tool-use payload arrives on stdin as JSON.
  - On detection: emit JSON permissionDecision deny on stdout, exit 0.
  - On clean: exit 0, no stdout.
  - Stderr is shown to the user.

Output schema:
  {
    "hookSpecificOutput": {
      "hookEventName": "PreToolUse",
      "permissionDecision": "deny",
      "permissionDecisionReason": "<explanation>"
    }
  }

Self-check:
  --self-check  Loads patterns.json and compiles every regex.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

# Allow `import _lib` when the hooks dir is on PYTHONPATH OR when this
# script is exec'd directly from ~/.ai/hooks/.
sys.path.insert(0, str(Path(__file__).resolve().parent))
import _lib  # noqa: E402


def deny(reason: str) -> None:
    """Emit a permission-deny decision via JSON stdout and exit 0."""
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason,
        }
    }))
    sys.exit(0)


def extract_command(payload: dict) -> str:
    """Best-effort extraction of the command being run from the
    Claude tool-use payload shape. Falls back to stringifying the
    whole payload, which still matches patterns."""
    if not isinstance(payload, dict):
        return json.dumps(payload)
    # Common shapes across Claude Code event versions.
    cmd = (
        payload.get("command")
        or payload.get("input", {}).get("command")
        or payload.get("params", {}).get("command")
        or payload.get("tool_input", {}).get("command")
    )
    if cmd:
        return cmd
    return json.dumps(payload)


def main(argv: list) -> int:
    if "--self-check" in argv:
        return _lib.self_check_ok()

    raw = sys.stdin.read()
    if not raw.strip():
        # No payload to inspect; allow by default.
        return 0

    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        # If we can't parse, still scan the raw text for patterns.
        payload = {"raw": raw}

    # Only guard PreToolUse events on Bash/shell tools.
    if isinstance(payload, dict):
        hook_event = (
            payload.get("hookEventName")
            or payload.get("hook_event_name")
            or ""
        )
        if hook_event and hook_event != "PreToolUse":
            return 0

        tool_name = payload.get("tool_name") or payload.get("toolName") or ""
        if tool_name and tool_name not in ("Bash", "shell", "execute"):
            return 0

        # Extract the command to scan.
        tool_input = (
            payload.get("tool_input")
            or payload.get("toolInput")
            or payload.get("toolArgs")
            or {}
        )
        if isinstance(tool_input, dict):
            command = tool_input.get("command") or tool_input.get("cmd") or ""
        else:
            command = extract_command(payload)
    else:
        command = raw

    if not command:
        return 0

    patterns = _lib.load_patterns()
    hits = _lib.scan_lines(command.splitlines() or [command], patterns)
    if not hits:
        return 0

    # Build a deny reason that does NOT echo the full secret value.
    # Take the first hit and construct a truncated/redacted snippet.
    hit = hits[0]
    pattern_id = hit.get("pattern_id", "unknown")
    severity = hit.get("severity", "medium")
    snippet = hit.get("snippet", "[redacted]")

    extra = ""
    if len(hits) > 1:
        extra = f" (and {len(hits) - 1} more match(es))"

    deny(
        f"Possible secret detected in Bash command: pattern={pattern_id} severity={severity}{extra}.\n"
        f"Snippet (redacted): {snippet}\n"
        "Per Common.md §1.P4 (no secrets in artifacts; non-overridable).\n"
        "Use OS clipboard transfer (Common.md §4.2) instead of embedding secrets in commands."
    )
    # deny() calls sys.exit(0); this return is unreachable but satisfies type checkers.
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
"""hooks/test-coverage-gate.py — detect source changes without corresponding test changes.

Fires on Stop and SubagentStop events. Inspects `git diff --name-only`
between HEAD and the upstream base branch. If source files changed but
no test files changed, emits TEST-COVERAGE-VIOLATION — non-blocking.

Test file detection heuristics (covers the common conventions):
  - Path segment is 'test', 'tests', '__tests__', 'spec', or 'specs'
  - Filename contains 'test_', '_test.', '.test.', '.spec.', '_spec.'
  - Filename ends with Test.kt / Test.java / Spec.rb / _test.go

Source file detection: any code file (.py, .ts, .tsx, .js, .jsx, .go,
  .rs, .java, .kt, .rb, .cs, .cpp, .c, .h, .swift, .sh, .bash) that
  does NOT match the test heuristics above.

Self-check:
  --self-check  exits 0 if git is reachable, 1 otherwise.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _lib  # noqa: E402


SOURCE_EXTENSIONS = {
    ".py", ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs",
    ".go", ".rs", ".java", ".kt", ".rb", ".cs",
    ".cpp", ".cc", ".cxx", ".c", ".h", ".hpp",
    ".swift", ".sh", ".bash",
}

TEST_PATH_SEGMENTS = {"test", "tests", "__tests__", "spec", "specs"}

TEST_NAME_PATTERNS = (
    "test_", "_test.", ".test.", ".spec.", "_spec.",
    "Test.kt", "Test.java", "Spec.rb", "_test.go",
)


def _ai_root() -> Path:
    return Path(os.environ.get("AI_ROOT", str(Path.home() / ".ai")))


def _utc_timestamp() -> str:
    return datetime.now(tz=timezone.utc).strftime("%Y-%m-%dT%H%M%S-%fZ")


def _git_root(cwd: Path) -> Path | None:
    try:
        r = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            capture_output=True, text=True, check=False, cwd=str(cwd),
        )
        if r.returncode == 0:
            return Path(r.stdout.strip())
    except FileNotFoundError:
        pass
    return None


def _base_ref(repo: Path) -> str:
    """Return the best available base ref to diff against.

    Priority: origin/main, origin/master, HEAD~1 (no remote).
    """
    for ref in ("origin/main", "origin/master"):
        r = subprocess.run(
            ["git", "rev-parse", "--verify", ref],
            capture_output=True, check=False, cwd=str(repo),
        )
        if r.returncode == 0:
            return ref
    return "HEAD~1"


def _changed_files(repo: Path, base: str) -> list[str]:
    """Return list of files changed between base and HEAD."""
    r = subprocess.run(
        ["git", "diff", "--name-only", base, "HEAD"],
        capture_output=True, text=True, check=False, cwd=str(repo),
    )
    if r.returncode != 0:
        return []
    return [f.strip() for f in r.stdout.splitlines() if f.strip()]


def is_test_file(path: str) -> bool:
    """Return True if path looks like a test/spec file."""
    p = Path(path)
    # Check path segments
    if any(seg.lower() in TEST_PATH_SEGMENTS for seg in p.parts):
        return True
    # Check filename patterns
    name = p.name
    return any(pat in name for pat in TEST_NAME_PATTERNS)


def is_source_file(path: str) -> bool:
    """Return True if path is a tracked source file (non-test code)."""
    p = Path(path)
    if p.suffix.lower() not in SOURCE_EXTENSIONS:
        return False
    return not is_test_file(path)


def write_violation_record(repo: Path, source_files: list[str]) -> None:
    vdir = _ai_root() / "audit" / "violations"
    try:
        vdir.mkdir(parents=True, exist_ok=True)
        ts = _utc_timestamp()
        fpath = vdir / f"{ts}-test-coverage-gate.md"
        listed = "\n".join(f"  - {f}" for f in source_files[:20])
        if len(source_files) > 20:
            listed += f"\n  ... and {len(source_files) - 20} more"
        content = (
            f"# Violation — {ts}\n\n"
            f"- **Repo:** {repo}\n"
            f"- **What happened:** {len(source_files)} source file(s) changed with no corresponding test file changes.\n"
            f"- **Changed source files:**\n{listed}\n"
            f"- **Remediation:** Add or update tests before marking this work done.\n"
        )
        fpath.write_text(content, encoding="utf-8")
    except Exception as e:  # noqa: BLE001
        _lib.log(f"warning: could not write violation record: {e}")


def check_repo(cwd: Path) -> list[str]:
    """Return violation lines for the repo at cwd, or empty list if clean."""
    repo = _git_root(cwd)
    if repo is None:
        return []
    base = _base_ref(repo)
    changed = _changed_files(repo, base)
    if not changed:
        return []

    source_files = [f for f in changed if is_source_file(f)]
    test_files = [f for f in changed if is_test_file(f)]

    if source_files and not test_files:
        write_violation_record(repo, source_files)
        summary = ", ".join(source_files[:3])
        if len(source_files) > 3:
            summary += f" (+{len(source_files) - 3} more)"
        return [
            f"TEST-COVERAGE-VIOLATION: {len(source_files)} source file(s) changed with no test changes in {repo}. Changed: {summary}"
        ]
    return []


def main() -> None:
    if "--self-check" in sys.argv:
        try:
            subprocess.run(["git", "--version"], capture_output=True, check=True)
        except (FileNotFoundError, subprocess.CalledProcessError) as e:
            _lib.log(f"self-check FAIL: {e}")
            sys.exit(1)
        _lib.log("self-check OK")
        sys.exit(0)

    try:
        event = json.load(sys.stdin)
    except (json.JSONDecodeError, EOFError):
        event = {}

    raw_cwd = (
        event.get("cwd")
        or event.get("workingDirectory")
        or os.getcwd()
    )
    cwd = Path(raw_cwd)

    violations = check_repo(cwd)

    if violations:
        for v in violations:
            _lib.log(v)
            print(v, flush=True)
    else:
        _lib.log("test-coverage-gate: no violation")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""hooks/worktree-guard.py — enforce worktree-based feature development.

Two rules, both implementing Common.md §U17:

1. BRANCH-IN-PRIMARY GUARD
   Block `git checkout -b <branch>` and `git switch -c <branch>` when
   running in the primary worktree. Feature work must live in a linked
   worktree so the primary repo stays on main. Redirect to
   `git worktree add`.

2. PLACEMENT GUARD
   When `git worktree add <path>` IS used, enforce canonical placement:
     <repo>/.worktrees/<name>/         (single-repo, dies with the repo)
     <repo>/.claude/worktrees/<name>/  (Claude Code native EnterWorktree)
     ~/.ai/worktrees/<name>/           (cross-repo, persistent)
   Ad-hoc placement (../<branch>/, /tmp/worktree-X/, etc.) is forbidden.

Known limitations (PreToolUse static parser): a `git checkout -b` or
`git worktree add` hidden inside a subshell (`(...)`), command
substitution (`$(...)` / backticks), or a delegated interpreter
(`bash -c "..."`) is not caught by static tokenization. The
client-agnostic wrapper mode (`ai wrap git`) is the backstop for those
— it inspects the real git argv.

Two invocation modes:
  PreToolUse  — reads a JSON event from stdin; on violation emits a
                JSON permissionDecision deny on stdout and exits 0.
                (Claude Code path via hooks.PreToolUse in settings.json)
  wrapper     — invoked as `python <hook> --mode=wrapper` by `ai wrap git`;
                reads git argv from $WRAPPED_ARGV; on violation writes to
                stderr and exits non-zero to block the real git binary.

Self-check:
  --self-check
"""
from __future__ import annotations

import json
import os
import shlex
import subprocess
import sys
from pathlib import Path
from typing import List, Optional

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _lib  # noqa: E402

# Flags on `git worktree add` that consume the next token as a value.
VALUE_FLAGS = {"-b", "-B", "--reason"}

# Shell operators that separate one command from the next.
SHELL_SEPARATORS = {";", "&&", "||", "|", "&"}

# `git` global options (before the subcommand) that consume the next token.
GIT_GLOBAL_VALUE_OPTS = {
    "-C", "-c", "--git-dir", "--work-tree",
    "--namespace", "--exec-path", "--super-prefix",
}


def deny_pretooluse(reason: str) -> None:
    """Emit a PreToolUse permission-deny decision (stdout) and exit 0."""
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason,
        }
    }))
    sys.exit(0)


def ai_worktrees_root() -> Path:
    """Return the cross-repo canonical worktree root."""
    ai_root = os.environ.get("AI_ROOT", str(Path.home() / ".ai"))
    return Path(ai_root) / "worktrees"


def _clean_path_env() -> dict:
    """Return os.environ with AI shim bin dirs stripped from PATH.

    resolve_repo_root and is_primary_worktree must reach the real git,
    not the ~/.ai/bin/git governance shim, to avoid re-entering the
    `ai wrap` pipeline which can deadlock or timeout.
    """
    canonical_ai_bin = Path.home() / ".ai" / "bin"
    env_ai_root = os.environ.get("AI_ROOT", "")
    override_ai_bin = Path(env_ai_root) / "bin" if env_ai_root else None

    strip = {str(canonical_ai_bin.resolve())}
    if override_ai_bin is not None:
        try:
            strip.add(str(override_ai_bin.resolve()))
        except Exception:
            strip.add(str(override_ai_bin))

    raw_path = os.environ.get("PATH", "")
    cleaned_parts = []
    for p in raw_path.split(os.pathsep):
        if not p:
            continue
        try:
            resolved = str(Path(p).resolve())
        except Exception:
            resolved = p
        if resolved not in strip and p not in strip:
            cleaned_parts.append(p)
    env = dict(os.environ)
    if cleaned_parts:
        env["PATH"] = os.pathsep.join(cleaned_parts)
    return env


def resolve_repo_root(cwd: str) -> Optional[Path]:
    """Return the repo root for the given working directory, or None."""
    try:
        out = subprocess.run(
            ["git", "-C", cwd, "rev-parse", "--show-toplevel"],
            capture_output=True, text=True, timeout=5,
            env=_clean_path_env(),
        )
        if out.returncode == 0 and out.stdout.strip():
            return Path(out.stdout.strip()).resolve()
    except Exception:
        pass
    return None


def is_primary_worktree(cwd: str) -> bool:
    """Return True if cwd is inside the primary (main) worktree.

    In a linked worktree, --git-dir and --git-common-dir differ. In the
    primary worktree they resolve to the same path.
    """
    try:
        git_dir = subprocess.run(
            ["git", "-C", cwd, "rev-parse", "--git-dir"],
            capture_output=True, text=True, timeout=5,
            env=_clean_path_env(),
        )
        common_dir = subprocess.run(
            ["git", "-C", cwd, "rev-parse", "--git-common-dir"],
            capture_output=True, text=True, timeout=5,
            env=_clean_path_env(),
        )
        if git_dir.returncode != 0 or common_dir.returncode != 0:
            return False
        gd = Path(git_dir.stdout.strip()).resolve()
        cd = Path(common_dir.stdout.strip()).resolve()
        return gd == cd
    except Exception:
        return False


def _normalize_tokens(tokens: List[str]) -> List[str]:
    """Expand tokens that have trailing semicolons glued on."""
    result: List[str] = []
    for tok in tokens:
        if tok.endswith(";") and tok != ";":
            result.append(tok[:-1])
            result.append(";")
        else:
            result.append(tok)
    return result


def _split_segments(tokens: List[str]) -> List[List[str]]:
    """Split a flat token list into command segments on shell operators."""
    segments: List[List[str]] = []
    current: List[str] = []
    for tok in _normalize_tokens(tokens):
        if tok in SHELL_SEPARATORS:
            if current:
                segments.append(current)
                current = []
        else:
            current.append(tok)
    if current:
        segments.append(current)
    return segments


def _is_env_assignment(tok: str) -> bool:
    """True for a leading `VAR=value` shell environment assignment."""
    if tok.startswith("-") or "=" not in tok:
        return False
    return tok.split("=", 1)[0].isidentifier()


def _skip_git_preamble(seg: List[str], start: int) -> int:
    """Skip env assignments and git global options; return index of subcommand."""
    i, n = start, len(seg)
    while i < n and _is_env_assignment(seg[i]):
        i += 1
    if i >= n or seg[i] != "git":
        return n  # not a git command
    i += 1
    while i < n and seg[i].startswith("-"):
        opt = seg[i]
        if "=" in opt:
            i += 1
        elif opt in GIT_GLOBAL_VALUE_OPTS and i + 1 < n:
            i += 2
        else:
            i += 1
    return i


# ── Rule 1: new-branch-in-primary detection ──────────────────────────────────

def _is_new_branch_in_segment(seg: List[str]) -> bool:
    """True if this segment creates a new git branch."""
    i = _skip_git_preamble(seg, 0)
    if i >= len(seg):
        return False
    subcmd = seg[i]
    flags = set(seg[i + 1:])
    if subcmd == "checkout" and (flags & {"-b", "-B"}):
        return True
    if subcmd == "switch" and (flags & {"-c", "-C"}):
        return True
    return False


def _has_new_branch_command(tokens: List[str]) -> bool:
    """True if any segment in tokens creates a new git branch."""
    return any(_is_new_branch_in_segment(seg) for seg in _split_segments(tokens))


def new_branch_deny_message(cwd: str) -> str:
    """Build the Rule 1 deny message with worktree-add guidance."""
    repo_root = resolve_repo_root(cwd)
    ai_root = ai_worktrees_root()
    hints = []
    if repo_root:
        hints.append(
            f"  git worktree add {repo_root}/.worktrees/<name> -b <branch>"
            "  (single-repo)"
        )
    hints.append(
        f"  git worktree add {ai_root}/<name> -b <branch>"
        "  (cross-repo / persistent)"
    )
    return (
        "Creating a branch in the primary worktree violates Common.md §U17.\n"
        "Feature work must live in a linked worktree so the primary repo "
        "stays on main.\n"
        "\nUse a worktree instead:\n"
        + "\n".join(hints) + "\n"
        "\nOr: `ai worktree add <name>` (with `--global` for cross-repo)."
    )


# ── Rule 2: placement detection ───────────────────────────────────────────────

def _path_after_add(seg: List[str], i: int) -> Optional[str]:
    """Return the positional path argument following `worktree add`."""
    n = len(seg)
    while i < n:
        tok = seg[i]
        if tok == "--":
            i += 1
            break
        if not tok.startswith("-"):
            return tok
        if tok in VALUE_FLAGS and i + 1 < n:
            i += 2
            continue
        i += 1
    if i < n:
        return seg[i]
    return None


def _worktree_add_path_in_segment(seg: List[str]) -> Optional[str]:
    """Return the target path if this segment is `git worktree add`."""
    i = _skip_git_preamble(seg, 0)
    n = len(seg)
    if i + 1 >= n or seg[i] != "worktree" or seg[i + 1] != "add":
        return None
    return _path_after_add(seg, i + 2)


def _worktree_add_paths(tokens: List[str]) -> List[str]:
    """Every `git worktree add` target path across the token segments."""
    paths: List[str] = []
    for seg in _split_segments(tokens):
        path = _worktree_add_path_in_segment(seg)
        if path is not None:
            paths.append(path)
    return paths


def _worktree_add_paths_in_command(command: str) -> List[str]:
    """All `git worktree add` paths in a raw shell command string."""
    paths: List[str] = []
    for line in command.splitlines():
        line_tokens = shlex.split(line, comments=False, posix=True)
        paths.extend(_worktree_add_paths(line_tokens))
    return paths


def is_canonical(raw_path: str, cwd: str) -> bool:
    """Return True if raw_path resolves to a canonical worktree location."""
    target = Path(raw_path)
    if not target.is_absolute():
        target = Path(cwd) / target
    try:
        resolved = target.resolve()
    except Exception:
        resolved = Path(os.path.normpath(str(target)))

    ai_root = ai_worktrees_root()
    try:
        resolved.relative_to(ai_root.resolve())
        return True
    except (ValueError, FileNotFoundError):
        pass

    repo_root = resolve_repo_root(cwd)
    if repo_root is not None:
        try:
            resolved.relative_to(repo_root / ".worktrees")
            return True
        except ValueError:
            pass
        try:
            # Claude Code's native EnterWorktree tool places worktrees here;
            # it can't be redirected to `ai worktree add`, so this harness-
            # managed root is canonical too.
            resolved.relative_to(repo_root / ".claude" / "worktrees")
            return True
        except ValueError:
            pass

    return False


def placement_deny_message(raw_path: str, cwd: str) -> str:
    """Build the Rule 2 deny message."""
    p = Path(raw_path)
    if not p.is_absolute():
        p = Path(cwd) / p
    try:
        shown = p.resolve()
    except Exception:
        shown = p

    repo_root = resolve_repo_root(cwd)
    ai_root = ai_worktrees_root()
    hints = []
    if repo_root:
        hints.append(f"  {repo_root}/.worktrees/<name>/  — single-repo")
        hints.append(f"  {repo_root}/.claude/worktrees/<name>/  — Claude Code native (EnterWorktree)")
    hints.append(f"  {ai_root}/<name>/  — cross-repo or persistent")
    return (
        "Worktree placement violates Common.md §U17.\n"
        f"  Target: {shown}\n"
        "Canonical roots:\n"
        + "\n".join(hints) + "\n"
        "Choose by lifecycle (§U17.1) and re-run.\n"
        "Preferred surface: `ai worktree add <name>` "
        "(with `--global` for cross-repo)."
    )


# ── Mode runners ──────────────────────────────────────────────────────────────

def run_pretooluse_mode() -> int:
    """Claude Code PreToolUse path: parse a JSON event from stdin."""
    raw = sys.stdin.read()
    if not raw.strip():
        return 0
    try:
        event = json.loads(raw)
    except json.JSONDecodeError:
        return 0

    hook_event = event.get("hookEventName") or event.get("hook_event_name") or ""
    if hook_event != "PreToolUse":
        return 0
    tool_name = event.get("tool_name") or event.get("toolName") or ""
    if tool_name not in ("Bash", "shell", "execute"):
        return 0
    tool_input = event.get("tool_input") or event.get("toolInput") or {}
    if not isinstance(tool_input, dict):
        return 0
    command = tool_input.get("command") or ""
    if not isinstance(command, str):
        return 0

    has_branch_op = "checkout" in command or "switch" in command
    has_worktree = "worktree" in command
    if not has_branch_op and not has_worktree:
        return 0

    cwd = event.get("cwd") or os.getcwd()

    # Rule 1: block new-branch creation in the primary worktree.
    if has_branch_op and is_primary_worktree(cwd):
        for line in command.splitlines():
            try:
                line_tokens = shlex.split(line, comments=False, posix=True)
            except ValueError:
                continue
            if _has_new_branch_command(line_tokens):
                deny_pretooluse(new_branch_deny_message(cwd))

    # Rule 2: enforce canonical placement when `git worktree add` is used.
    if has_worktree:
        try:
            targets = _worktree_add_paths_in_command(command)
        except ValueError:
            deny_pretooluse(
                "worktree-guard: could not parse a command containing "
                "'worktree'; denying per fail-closed policy (Common.md §U17)."
            )
            return 0
        for target in targets:
            if not is_canonical(target, cwd):
                deny_pretooluse(placement_deny_message(target, cwd))

    return 0


def run_wrapper_mode() -> int:
    """Client-agnostic `ai wrap git` path: git argv arrives in $WRAPPED_ARGV."""
    argv_json = os.environ.get("WRAPPED_ARGV", "")
    if not argv_json:
        return 0
    try:
        argv = json.loads(argv_json)
    except json.JSONDecodeError:
        return 0
    if not isinstance(argv, list):
        return 0

    tokens = ["git"] + [str(a) for a in argv]
    cwd = os.getcwd()

    # Rule 1: block new-branch creation in the primary worktree.
    if ("checkout" in tokens or "switch" in tokens):
        if _has_new_branch_command(tokens) and is_primary_worktree(cwd):
            sys.stderr.write(new_branch_deny_message(cwd) + "\n")
            return 1

    # Rule 2: enforce canonical placement.
    if "worktree" in tokens:
        for target in _worktree_add_paths(tokens):
            if not is_canonical(target, cwd):
                sys.stderr.write(placement_deny_message(target, cwd) + "\n")
                return 1

    return 0


def main() -> int:
    if "--self-check" in sys.argv:
        return _lib.self_check_ok()
    if "--mode=wrapper" in sys.argv or os.environ.get("WRAPPED_CMD"):
        return run_wrapper_mode()
    return run_pretooluse_mode()


if __name__ == "__main__":
    sys.exit(main())

